        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int m = (int) in.nval;
        int[][] pairs = new int[m][2];
        for (int i = 0; i < m; i++) {
            in.nextToken();
            pairs[i][0] = (int) in.nval;
